-- Dashboard and reporting queries: aggregates, GROUPING SETS, FILTER, CTE chains
SELECT date_trunc('day', created_at) AS day, COUNT(*) AS orders, SUM(total_cents) / 100.0 AS revenue FROM orders WHERE created_at >= date_trunc('month', now()) - INTERVAL '1 month' GROUP BY 1 ORDER BY 1;
SELECT COUNT(*) FILTER (WHERE status = 'paid') AS paid, COUNT(*) FILTER (WHERE status = 'refunded') AS refunded, AVG(total_cents) FILTER (WHERE status = 'paid') AS avg_paid FROM orders;
SELECT region, product_category, SUM(amount) AS total FROM sales GROUP BY GROUPING SETS ((region, product_category), (region), ()) ORDER BY region, product_category;
SELECT region, product_category, SUM(amount) FROM sales GROUP BY ROLLUP (region, product_category);
SELECT region, channel, SUM(amount), GROUPING(region, channel) AS g FROM sales GROUP BY CUBE (region, channel);
SELECT extract(year FROM created_at) AS yr, extract(month FROM created_at) AS mo, COUNT(DISTINCT user_id) AS mau FROM events GROUP BY 1, 2 ORDER BY 1, 2;
WITH monthly AS (SELECT date_trunc('month', created_at) AS m, SUM(total_cents) AS revenue FROM orders GROUP BY 1), growth AS (SELECT m, revenue, LAG(revenue) OVER (ORDER BY m) AS prev FROM monthly) SELECT m, revenue, ROUND(100.0 * (revenue - prev) / NULLIF(prev, 0), 2) AS pct_growth FROM growth ORDER BY m;
WITH RECURSIVE tree AS (SELECT id, parent_id, name, 1 AS depth, ARRAY[id] AS path FROM categories WHERE parent_id IS NULL UNION ALL SELECT c.id, c.parent_id, c.name, t.depth + 1, t.path || c.id FROM categories c JOIN tree t ON c.parent_id = t.id WHERE NOT c.id = ANY(t.path)) SELECT * FROM tree ORDER BY path;
WITH RECURSIVE nums(n) AS (VALUES (1) UNION ALL SELECT n + 1 FROM nums WHERE n < 10) SELECT n FROM nums;
WITH cohort AS (SELECT user_id, date_trunc('week', MIN(created_at)) AS cohort_week FROM events GROUP BY user_id), activity AS (SELECT e.user_id, date_trunc('week', e.created_at) AS active_week FROM events e GROUP BY 1, 2) SELECT c.cohort_week, (a.active_week - c.cohort_week) / 7 AS week_no, COUNT(DISTINCT a.user_id) AS users FROM cohort c JOIN activity a USING (user_id) GROUP BY 1, 2 ORDER BY 1, 2;
SELECT p.category, p.name, p.price FROM products p WHERE p.price > (SELECT AVG(price) FROM products WHERE category = p.category);
SELECT c.name, (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.id) AS n_orders, (SELECT MAX(o.created_at) FROM orders o WHERE o.customer_id = c.id) AS last_order FROM customers c;
SELECT * FROM (SELECT department, salary, RANK() OVER (PARTITION BY department ORDER BY salary DESC) AS rnk FROM employees) t WHERE rnk <= 3;
SELECT o.id, c.name, p.name, oi.quantity FROM orders o INNER JOIN customers c ON c.id = o.customer_id INNER JOIN order_items oi ON oi.order_id = o.id INNER JOIN products p ON p.id = oi.product_id LEFT JOIN shipments s ON s.order_id = o.id LEFT JOIN warehouses w ON w.id = s.warehouse_id WHERE w.region = 'EU' OR s.id IS NULL;
SELECT a.id FROM a FULL OUTER JOIN b ON a.id = b.id WHERE a.id IS NULL OR b.id IS NULL;
SELECT * FROM a CROSS JOIN b;
SELECT * FROM a NATURAL JOIN b;
SELECT id FROM t1 UNION SELECT id FROM t2 EXCEPT SELECT id FROM t3;
(SELECT id FROM t1 ORDER BY id LIMIT 5) UNION ALL (SELECT id FROM t2 ORDER BY id DESC LIMIT 5);
SELECT id FROM t1 INTERSECT ALL SELECT id FROM t2;
SELECT CASE WHEN total_cents < 1000 THEN 'small' WHEN total_cents < 10000 THEN 'medium' ELSE 'large' END AS bucket, COUNT(*) FROM orders GROUP BY 1;
SELECT COALESCE(NULLIF(trim(name), ''), 'unknown') AS name, GREATEST(a, b, c) AS mx, LEAST(a, b) AS mn FROM t;
SELECT customer_id, SUM(total_cents) AS spend FROM orders GROUP BY customer_id ORDER BY spend DESC NULLS LAST LIMIT 10;
SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY response_ms) AS p50, percentile_cont(0.95) WITHIN GROUP (ORDER BY response_ms) AS p95 FROM requests;
SELECT mode() WITHIN GROUP (ORDER BY status_code) FROM requests;
SELECT string_agg(name, ', ' ORDER BY name) AS names, array_agg(DISTINCT tag) AS tags FROM items GROUP BY category;
SELECT bool_and(active), bool_or(active), every(active) FROM users;
SELECT * FROM sales TABLESAMPLE SYSTEM (10);
